#!/usr/bin/env node
// bundle copy generated by scripts/sync-assets.mjs: main-guard keyed on CCO_HOOK_MAIN (see resources/entry/cco-hook-bundle.mjs)
/**
 * beforeShellExecution hook: block a short list of clearly destructive commands.
 * Everything else is allowed. Fail-open on any error.
 */
import { readStdin, safeJsonParse, workspaceFromPayload, workspacePaths, hookLog, emit, isEnabled } from "./lib/common.mjs";
import { loadConfig } from "./lib/config.mjs";

const EXPLICITLY_ALLOWED = [
  /^rm\s+-rf\s+(\.\/)?(node_modules|dist|build|\.next|\.turbo|coverage)(\s|$)/
];

const BLOCKED = [
  [/(^|[;&|]\s*)rm\s+-rf?\s+(\/|~|\$home|\*)(\s|$)/, "recursive delete of / or home"],
  [/\bmkfs(\.\w+)?\b/, "filesystem format"],
  [/\bdd\s+if=.*\bof=\/dev\//, "raw disk write"],
  [/\b(shutdown|reboot|halt|poweroff)\b/, "power operation"],
  [/\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(ba|z|da)?sh\b/, "pipe remote script to shell"],
  [/\bgit\s+push\b.*(--force|-f)\b.*\b(main|master)\b/, "force push to main"],
  [/\bDROP\s+(DATABASE|SCHEMA)\b/i, "drop database"]
];

export function classifyCommand(cmdRaw) {
  const cmd = String(cmdRaw || "").trim().toLowerCase();
  if (EXPLICITLY_ALLOWED.some((re) => re.test(cmd))) {
    return { blocked: false, reason: "explicitly_allowed" };
  }
  for (const [re, reason] of BLOCKED) {
    if (re.test(cmd)) {
      return { blocked: true, reason };
    }
  }
  return { blocked: false, reason: null };
}

async function main() {
  const payload = safeJsonParse((await readStdin()).trim() || "{}");
  const workspace = workspaceFromPayload(payload);
  const paths = workspace ? workspacePaths(workspace) : null;
  try {
    const config = loadConfig(workspace);
    if (!workspace || !isEnabled(workspace).enabled || config?.shellGuard?.enabled !== true) {
      emit({ continue: true, permission: "allow" });
      return;
    }
    const cmdRaw = String(payload.command ?? payload.shellCommand ?? payload.text ?? "").trim();
    const verdict = classifyCommand(cmdRaw);
    hookLog(paths, { event: "beforeShellExecution", allowed: !verdict.blocked, reason: verdict.reason, command: cmdRaw.slice(0, 300) });
    if (verdict.blocked) {
      const msg = `CCO shell guard blocked a potentially destructive command (${verdict.reason}):\n${cmdRaw}\nRun it manually outside the agent if you really intend it.`;
      emit({ continue: false, permission: "deny", user_message: msg, agent_message: msg });
      return;
    }
    emit({ continue: true, permission: "allow" });
  } catch {
    emit({ continue: true, permission: "allow" });
  }
}

if (process.env.CCO_HOOK_MAIN === "cco-shell-guard.mjs") {
  main().catch(() => emit({ continue: true, permission: "allow" }));
}
